-- Măsurarea punctului 8 (D-018, C-002): interogările unei cereri GET /api/statii/1051/plecari
-- pentru Gară (stop_id 1051, stația cu cele mai multe plecări: 1.730 în stop_times), joi 26.11.2026,
-- ora 16:00, pe versiunea de feed 1 (arhiva tursib.gtfs_2026-10-v4.9.zip, SHA-256 cb0ddad9…).
-- Ordinea și textul sunt cele din cod (ServiceCalendar, Stations, Departures, NextDepartures), cu
-- parametrii scriși direct. Fereastra: de joi 16:00 până sâmbătă 00:00, deci zilele de serviciu
-- 25.11 (3, E2026), 26.11 (3, E2026), 27.11 (3, E2026) și 28.11 (4).
-- Rulare: Neon SQL Editor sau psql; pragul (300 ms) e pe suma „Execution Time” (DATA.md → Performanță).
-- Generat din baza locală; lista de curse din pasul 12 vine din rezultatul pașilor 6, 8, 10 și 11.


-- 1. eticheta zilei: sărbătoare legală?
explain (analyze, buffers) select exists (select 1 from public_holidays where date = date '2026-11-26');

-- 2. versiunea de feed activă
explain (analyze, buffers) select id from feed_versions where active;

-- 3. stația (D-031)
explain (analyze, buffers) select s.stop_id, x.stop_name
from stops x
join stops s on s.feed_version_id = x.feed_version_id
            and s.stop_name = x.stop_name
            and ST_DWithin(s.geog, x.geog, 150)
where x.feed_version_id = 1 and x.stop_id = '1051'
order by s.stop_id;

-- 4. serviciile active pe 25.11
explain (analyze, buffers) select service_id from calendar
 where feed_version_id = 1 and date '2026-11-25' between start_date and end_date and wednesday
union select service_id from calendar_dates
 where feed_version_id = 1 and date = date '2026-11-25' and exception_type = 1
except select service_id from calendar_dates
 where feed_version_id = 1 and date = date '2026-11-25' and exception_type = 2
order by service_id;

-- 5. serviciile active pe 26.11
explain (analyze, buffers) select service_id from calendar
 where feed_version_id = 1 and date '2026-11-26' between start_date and end_date and thursday
union select service_id from calendar_dates
 where feed_version_id = 1 and date = date '2026-11-26' and exception_type = 1
except select service_id from calendar_dates
 where feed_version_id = 1 and date = date '2026-11-26' and exception_type = 2
order by service_id;

-- 6. plecările din ziua de serviciu 25.11
explain (analyze, buffers) select st.stop_id, st.stop_sequence, st.departure_sec, st.trip_id,
       r.route_short_name, t.direction_id, t.trip_headsign
from stop_times st
join trips t on t.feed_version_id = st.feed_version_id and t.trip_id = st.trip_id
join routes r on r.feed_version_id = t.feed_version_id and r.route_id = t.route_id
where st.feed_version_id = 1
  and st.stop_id in ('1051')
  and st.departure_sec >= 144000 and st.departure_sec < 259200
  and t.service_id in ('3', 'E2026');

-- 7. serviciile active pe 27.11
explain (analyze, buffers) select service_id from calendar
 where feed_version_id = 1 and date '2026-11-27' between start_date and end_date and friday
union select service_id from calendar_dates
 where feed_version_id = 1 and date = date '2026-11-27' and exception_type = 1
except select service_id from calendar_dates
 where feed_version_id = 1 and date = date '2026-11-27' and exception_type = 2
order by service_id;

-- 8. plecările din ziua de serviciu 26.11
explain (analyze, buffers) select st.stop_id, st.stop_sequence, st.departure_sec, st.trip_id,
       r.route_short_name, t.direction_id, t.trip_headsign
from stop_times st
join trips t on t.feed_version_id = st.feed_version_id and t.trip_id = st.trip_id
join routes r on r.feed_version_id = t.feed_version_id and r.route_id = t.route_id
where st.feed_version_id = 1
  and st.stop_id in ('1051')
  and st.departure_sec >= 57600 and st.departure_sec < 172800
  and t.service_id in ('3', 'E2026');

-- 9. serviciile active pe 28.11
explain (analyze, buffers) select service_id from calendar
 where feed_version_id = 1 and date '2026-11-28' between start_date and end_date and saturday
union select service_id from calendar_dates
 where feed_version_id = 1 and date = date '2026-11-28' and exception_type = 1
except select service_id from calendar_dates
 where feed_version_id = 1 and date = date '2026-11-28' and exception_type = 2
order by service_id;

-- 10. plecările din ziua de serviciu 27.11
explain (analyze, buffers) select st.stop_id, st.stop_sequence, st.departure_sec, st.trip_id,
       r.route_short_name, t.direction_id, t.trip_headsign
from stop_times st
join trips t on t.feed_version_id = st.feed_version_id and t.trip_id = st.trip_id
join routes r on r.feed_version_id = t.feed_version_id and r.route_id = t.route_id
where st.feed_version_id = 1
  and st.stop_id in ('1051')
  and st.departure_sec >= -28800 and st.departure_sec < 86400
  and t.service_id in ('3', 'E2026');

-- 11. plecările din ziua de serviciu 28.11
explain (analyze, buffers) select st.stop_id, st.stop_sequence, st.departure_sec, st.trip_id,
       r.route_short_name, t.direction_id, t.trip_headsign
from stop_times st
join trips t on t.feed_version_id = st.feed_version_id and t.trip_id = st.trip_id
join routes r on r.feed_version_id = t.feed_version_id and r.route_id = t.route_id
where st.feed_version_id = 1
  and st.stop_id in ('1051')
  and st.departure_sec >= -115200 and st.departure_sec < 0
  and t.service_id in ('4');

